export interface CallbackHandlerContext {
  apiClient: TelegramApiClient;
  config: TelegramPlatformConfig;
  emojiRegistry: CustomEmojiRegistry;
  userService: TelegramUserService;
  prayerAdapter: TelegramPrayerAdapter;
  contentAdapter: TelegramIslamicContentAdapter;
  academyQuizService: TelegramAcademyQuizService;
  supportService: TelegramSupportService;
  broadcastManager: TelegramBroadcastManager;
  contentStudio: TelegramContentStudio;
  aiBridge: TelegramAiBridge;
  adminService: TelegramAdminService;
  channelService: TelegramChannelService;
  publishingService: TelegramPublishingService;
  repository: TelegramRepository;
  appReleaseService: AppReleaseService;
  centralAdminWriter?: import('../types').TelegramCentralAdminWriter;
  runDiagnostics: () => Promise<{
    readyToAnswerStart: boolean;
    mode: string;
    startupState: string;
    telegramApi: { connected: boolean; botUsername?: string; error?: string };
    issues: string[];
  }>;
}

async function renderScreenUpdate(
  apiClient: TelegramApiClient,
  callback: TelegramApiCallbackQuery,
  payload: {
    text: string;
    entities?: TelegramMessageEntity[];
    reply_markup: TelegramInlineKeyboardMarkup;
  }
) {
  const chatId = callback.message?.chat.id || callback.from.id;
  const messageId = callback.message?.message_id;

  if (messageId) {
    const edited = await apiClient.editMessageText({
      chat_id: chatId,
      message_id: messageId,
      text: payload.text,
      ...(payload.entities && payload.entities.length > 0 ? { entities: payload.entities } : {}),
      reply_markup: payload.reply_markup,
      disable_web_page_preview: true,
    });
    if (
      edited.ok ||
      String(edited.description || '').toLowerCase().includes('message is not modified')
    ) {
      return;
    }
  }

  await apiClient.sendMessage({
    chat_id: chatId,
    text: payload.text,
    ...(payload.entities && payload.entities.length > 0 ? { entities: payload.entities } : {}),
    reply_markup: payload.reply_markup,
    disable_web_page_preview: true,
  });
}

export async function handleCallbackQuery(
  callback: TelegramApiCallbackQuery,
  user: TelegramUserRecord,
  ctx: CallbackHandlerContext
): Promise<{ handled: boolean; action: string }> {
  const data = (callback.data || '').trim();
  const chatId = callback.message?.chat.id || callback.from.id;
  const dict = getTelegramLocaleBundle(user.language);
  const role = ctx.adminService.getEffectiveRole(user.telegramId);
  const settings = ctx.repository.getSettings();
  const menuOpts = { isAdmin: Boolean(role), miniAppEnabled: Boolean(settings.miniAppEnabled) };

  // Exit AI session when navigating away from AI controls
  if (data !== 'nav:ai' && data !== 'ai:clear') {
    ctx.aiBridge.exitAiMode(user.telegramId);
  }

  // 1. Onboarding or Language Selection: onboard:lang:<locale> | lang:<locale>
  if (data.startsWith('onboard:lang:') || data.startsWith('lang:')) {
    const requestedLocale = data.startsWith('onboard:lang:')
      ? data.slice('onboard:lang:'.length)
      : data.slice('lang:'.length);

    if (!isValidTelegramLocale(requestedLocale)) {
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: dict.genericError,
      });
      return { handled: true, action: 'lang:invalid' };
    }

    const updatedUser =
      (await ctx.userService.setUserLanguage(user.telegramId, requestedLocale)) || {
        ...user,
        language: requestedLocale,
        onboardingCompleted: true,
      };
    const nextDict = getTelegramLocaleBundle(updatedUser.language);
    const formatted = ctx.emojiRegistry.formatMessage(
      `${nextDict.languageChangedMessage}\n\n${nextDict.mainMenuPrompt}`
    );

    await ctx.apiClient.answerCallbackQuery({
      callback_query_id: callback.id,
      text: nextDict.languageChangedToast,
    });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildMainMenuKeyboard(updatedUser.language, ctx.emojiRegistry, ctx.config, menuOpts),
    });

    // Refresh persistent Reply Keyboard in the newly chosen language
    if (data.startsWith('onboard:lang:')) {
      await ctx.apiClient.sendMessage({
        chat_id: chatId,
        text: nextDict.mainMenuTitle.replace(/\{\{emoji:[^}]+\}\}\s*/g, ''),
        reply_markup: buildPersistentReplyKeyboard(updatedUser.language),
      });
    }
    return { handled: true, action: data };
  }

  // 2. Settings Toggles & Stop All Opt-Out
  if (data === 'settings:stop_all') {
    const updatedUser = (await ctx.userService.optOutAllNotifications(user.telegramId)) || user;
    const nextDict = getTelegramLocaleBundle(updatedUser.language);
    await ctx.apiClient.answerCallbackQuery({
      callback_query_id: callback.id,
      text: nextDict.settingUpdatedToast,
    });
    const formatted = ctx.emojiRegistry.formatMessage(nextDict.stopOptOutMessage);
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildSettingsKeyboard(updatedUser, ctx.emojiRegistry),
    });
    return { handled: true, action: 'settings:stop_all' };
  }

  if (data.startsWith('settings:toggle:')) {
    const field = data.slice('settings:toggle:'.length);
    if (
      field === 'prayerNotificationsEnabled' ||
      field === 'dailyWisdomEnabled' ||
      field === 'announcementsEnabled'
    ) {
      const updatedUser = (await ctx.userService.toggleSetting(user.telegramId, field)) || user;
      const nextDict = getTelegramLocaleBundle(updatedUser.language);
      const formatted = formatSettingsMessageText(updatedUser, ctx.emojiRegistry);

      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: nextDict.settingUpdatedToast,
      });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildSettingsKeyboard(updatedUser, ctx.emojiRegistry),
      });
      return { handled: true, action: `settings:toggle:${field}` };
    }
  }

  // 3. Prayer Extras: prayer:ramadan | prayer:calendar
  if (data === 'prayer:ramadan') {
    const formatted = ctx.prayerAdapter.formatRamadanModeMessage(user.language, ctx.emojiRegistry);
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildPrayerKeyboard(
        user.language,
        ctx.emojiRegistry,
        ctx.config,
        menuOpts.miniAppEnabled
      ),
    });
    return { handled: true, action: 'prayer:ramadan' };
  }

  if (data === 'prayer:calendar') {
    const formatted = ctx.prayerAdapter.formatReligiousCalendarMessage(
      user.language,
      ctx.emojiRegistry
    );
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildPrayerKeyboard(
        user.language,
        ctx.emojiRegistry,
        ctx.config,
        menuOpts.miniAppEnabled
      ),
    });
    return { handled: true, action: 'prayer:calendar' };
  }

  // 4. Quran, 114 Surahs Pagination, Tafsir, Khatm, Bookmarks
  if (data.startsWith('quran:ayah:')) {
    const idx = Number(data.slice('quran:ayah:'.length)) || 0;
    const res = ctx.contentAdapter.formatQuranDailyAyah(idx, user.language, ctx.emojiRegistry);
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: res.formatted.text,
      entities: res.formatted.entities,
      reply_markup: buildQuranKeyboard(
        user.language,
        res.index,
        res.total,
        ctx.emojiRegistry,
        ctx.config,
        menuOpts.miniAppEnabled
      ),
    });
    return { handled: true, action: data };
  }

  if (data === 'quran:surahs' || data.startsWith('quran:surahs:')) {
    const page = data.startsWith('quran:surahs:') ? Number(data.slice('quran:surahs:'.length)) || 0 : 0;
    const paged = ctx.contentAdapter.getSurahPage(page, 10);
    const formatted = ctx.emojiRegistry.formatMessage(
      `${dict.quranTitle}\n\n{{emoji:brand.book}} ${dict.buttons.allSurahs} (${paged.page + 1}/${paged.totalPages}):`
    );
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildSurahListKeyboard(
        user.language,
        paged.items,
        ctx.emojiRegistry,
        paged.page,
        paged.totalPages
      ),
    });
    return { handled: true, action: data };
  }

  if (data.startsWith('quran:surah:')) {
    const num = Number(data.slice('quran:surah:'.length)) || 1;
    const formatted = ctx.contentAdapter.formatSurahCard(num, user.language, ctx.emojiRegistry);
    const page = Math.floor((num - 1) / 10);
    const paged = ctx.contentAdapter.getSurahPage(page, 10);
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildSurahListKeyboard(
        user.language,
        paged.items,
        ctx.emojiRegistry,
        paged.page,
        paged.totalPages
      ),
    });
    return { handled: true, action: data };
  }

  if (data.startsWith('quran:tafsir:')) {
    const idx = Number(data.slice('quran:tafsir:'.length)) || 0;
    const res = ctx.contentAdapter.formatTafsirCard(idx, user.language, ctx.emojiRegistry);
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: res.formatted.text,
      entities: res.formatted.entities,
      reply_markup: buildTafsirKeyboard(user.language, res.index, res.total, ctx.emojiRegistry),
    });
    return { handled: true, action: data };
  }

  if (data === 'quran:khatm') {
    const card = ctx.contentAdapter.formatKhatmCard(
      ctx.repository,
      user.telegramId,
      user.language,
      ctx.emojiRegistry
    );
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: card.text,
      entities: card.entities,
      reply_markup: buildKhatmKeyboard(user.language, ctx.emojiRegistry),
    });
    return { handled: true, action: 'quran:khatm' };
  }

  if (data === 'quran:khatm:log_juz') {
    await ctx.contentAdapter.logKhatmJuzCompleted(ctx.repository, user.telegramId);
    const card = ctx.contentAdapter.formatKhatmCard(
      ctx.repository,
      user.telegramId,
      user.language,
      ctx.emojiRegistry
    );
    await ctx.apiClient.answerCallbackQuery({
      callback_query_id: callback.id,
      text: '+1 Juz saqlandi!',
    });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: card.text,
      entities: card.entities,
      reply_markup: buildKhatmKeyboard(user.language, ctx.emojiRegistry),
    });
    return { handled: true, action: 'quran:khatm:log_juz' };
  }

  if (data === 'quran:khatm:set_days') {
    await ctx.userService.setActiveFlow(user.telegramId, { type: 'khatm_set_days' });
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: dict.khatmSetDaysPrompt,
      reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
    });
    return { handled: true, action: 'quran:khatm:set_days' };
  }

  if (data === 'quran:search') {
    await ctx.userService.setActiveFlow(user.telegramId, { type: 'quran_search' });
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: dict.searchPrompt,
      reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
    });
    return { handled: true, action: 'quran:search' };
  }

  if (data.startsWith('bookmark:ayah:')) {
    const idx = Number(data.slice('bookmark:ayah:'.length)) || 0;
    const item = ctx.contentAdapter.formatQuranDailyAyah(idx, user.language, ctx.emojiRegistry);
    const toggled = await ctx.contentAdapter.toggleBookmark(ctx.repository, user.telegramId, {
      id: `ayah_${item.ayahId}`,
      kind: 'ayah',
      refId: item.ayahId,
      title: item.title,
    });
    await ctx.apiClient.answerCallbackQuery({
      callback_query_id: callback.id,
      text: toggled.saved ? dict.bookmarkSavedToast : dict.bookmarkRemovedToast,
    });
    return { handled: true, action: data };
  }

  if (data.startsWith('bookmark:hadith:')) {
    const idx = Number(data.slice('bookmark:hadith:'.length)) || 0;
    const item = ctx.contentAdapter.formatHadithCard(idx, user.language, ctx.emojiRegistry);
    const toggled = await ctx.contentAdapter.toggleBookmark(ctx.repository, user.telegramId, {
      id: `hadith_${item.hadithId}`,
      kind: 'hadith',
      refId: item.hadithId,
      title: item.title,
    });
    await ctx.apiClient.answerCallbackQuery({
      callback_query_id: callback.id,
      text: toggled.saved ? dict.bookmarkSavedToast : dict.bookmarkRemovedToast,
    });
    return { handled: true, action: data };
  }

  // 5. Hadith Callbacks: hadith:view:<idx> | hadith:col:<col>:<idx> | hadith:search
  if (data === 'hadith:search') {
    await ctx.userService.setActiveFlow(user.telegramId, { type: 'hadith_search' });
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: dict.searchPrompt,
      reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
    });
    return { handled: true, action: 'hadith:search' };
  }

  if (data.startsWith('hadith:view:') || data.startsWith('hadith:col:')) {
    let col: 'all' | 'bukhari' | 'muslim' | 'nawawi' = 'all';
    let idx = 0;
    if (data.startsWith('hadith:col:')) {
      const parts = data.split(':');
      const rawCol = parts[2];
      if (rawCol === 'bukhari' || rawCol === 'muslim' || rawCol === 'nawawi') col = rawCol;
      idx = Number(parts[3]) || 0;
    } else {
      idx = Number(data.slice('hadith:view:'.length)) || 0;
    }

    const filtered = ctx.contentAdapter.getHadithsByCollection(col);
    const totalFiltered = filtered.length || 1;
    const safeSubIdx = ((idx % totalFiltered) + totalFiltered) % totalFiltered;
    const targetHadith = filtered[safeSubIdx];
    const allList = ctx.contentAdapter.getHadithsByCollection('all');
    const globalIdx = Math.max(0, allList.findIndex((h) => h.id === targetHadith?.id));

    const res = ctx.contentAdapter.formatHadithCard(globalIdx, user.language, ctx.emojiRegistry);
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: res.formatted.text,
      entities: res.formatted.entities,
      reply_markup: buildHadithKeyboard(
        user.language,
        safeSubIdx,
        totalFiltered,
        ctx.emojiRegistry,
        col
      ),
    });
    return { handled: true, action: data };
  }

  // 6. Dhikr, Interactive Tasbeh (with goal persistence), Situational Duas
  if (data.startsWith('dhikr:view:')) {
    const idx = Number(data.slice('dhikr:view:'.length)) || 0;
    const eng = ctx.repository.getUserEngagement(user.telegramId);
    const probe = ctx.contentAdapter.formatDhikrCard(idx, 0, user.language, ctx.emojiRegistry);
    const savedCount = eng.dhikr.countsByDhikrId[probe.dhikrId] || 0;
    const savedGoal = eng.dhikr.dailyGoals[probe.dhikrId];
    const res = ctx.contentAdapter.formatDhikrCard(
      idx,
      savedCount,
      user.language,
      ctx.emojiRegistry,
      savedGoal,
      eng.dhikr.todayCount
    );
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: res.formatted.text,
      entities: res.formatted.entities,
      reply_markup: buildDhikrKeyboard(
        user.language,
        res.index,
        res.total,
        savedCount,
        ctx.emojiRegistry
      ),
    });
    return { handled: true, action: data };
  }

  if (data.startsWith('dhikr:tasbeh:')) {
    const parts = data.split(':');
    const idx = Number(parts[2]) || 0;
    const nextCount = Math.max(0, Math.min(99999, Number(parts[3]) || 0));
    const probe = ctx.contentAdapter.formatDhikrCard(idx, nextCount, user.language, ctx.emojiRegistry);
    const dhikrState = await ctx.contentAdapter.incrementTasbeh(
      ctx.repository,
      user.telegramId,
      probe.dhikrId,
      nextCount
    );
    const savedGoal = dhikrState.dailyGoals[probe.dhikrId];
    const res = ctx.contentAdapter.formatDhikrCard(
      idx,
      nextCount,
      user.language,
      ctx.emojiRegistry,
      savedGoal,
      dhikrState.todayCount
    );
    await ctx.apiClient.answerCallbackQuery({
      callback_query_id: callback.id,
      text: `${nextCount} / ${res.targetCount}`,
    });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: res.formatted.text,
      entities: res.formatted.entities,
      reply_markup: buildDhikrKeyboard(
        user.language,
        res.index,
        res.total,
        nextCount,
        ctx.emojiRegistry
      ),
    });
    return { handled: true, action: `dhikr:tasbeh:${idx}:${nextCount}` };
  }

  if (data.startsWith('dhikr:goal:')) {
    const idx = Number(data.slice('dhikr:goal:'.length)) || 0;
    await ctx.userService.setActiveFlow(user.telegramId, {
      type: 'tasbeh_set_goal',
      dhikrIndex: idx,
    });
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: dict.tasbehSetGoalPrompt,
      reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
    });
    return { handled: true, action: data };
  }

  if (data.startsWith('dua:view:')) {
    const idx = Number(data.slice('dua:view:'.length)) || 0;
    const res = ctx.contentAdapter.formatSituationalDuaCard(idx, user.language, ctx.emojiRegistry);
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: res.formatted.text,
      entities: res.formatted.entities,
      reply_markup: buildDuaKeyboard(user.language, res.index, res.total, ctx.emojiRegistry),
    });
    return { handled: true, action: data };
  }

  // 7. Islamic Academy, Quiz & Leaderboard
  if (data.startsWith('academy:lesson:')) {
    const idx = Number(data.slice('academy:lesson:'.length)) || 0;
    const res = ctx.academyQuizService.formatLessonCard(
      idx,
      user.telegramId,
      user.language,
      ctx.emojiRegistry
    );
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: res.formatted.text,
      entities: res.formatted.entities,
      reply_markup: buildAcademyKeyboard(
        user.language,
        res.index,
        res.total,
        res.lessonId,
        ctx.emojiRegistry
      ),
    });
    return { handled: true, action: data };
  }

  if (data.startsWith('academy:done:')) {
    const parts = data.split(':');
    const idx = Number(parts[2]) || 0;
    const lessonId = parts[3] || '';
    const done = await ctx.academyQuizService.toggleLessonCompleted(user.telegramId, lessonId);
    const res = ctx.academyQuizService.formatLessonCard(
      idx,
      user.telegramId,
      user.language,
      ctx.emojiRegistry
    );
    await ctx.apiClient.answerCallbackQuery({
      callback_query_id: callback.id,
      text: done ? '✅ Dars yakunlandi!' : 'Holat yangilandi',
    });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: res.formatted.text,
      entities: res.formatted.entities,
      reply_markup: buildAcademyKeyboard(
        user.language,
        res.index,
        res.total,
        res.lessonId,
        ctx.emojiRegistry
      ),
    });
    return { handled: true, action: data };
  }

  if (data === 'quiz:start') {
    const started = ctx.academyQuizService.startQuizSession(user.telegramId, 5);
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    if (!started.currentQuestion) {
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: dict.quizEmpty,
        reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'quiz:start:empty' };
    }
    const q = started.currentQuestion;
    const formatted = ctx.emojiRegistry.formatMessage(
      `${dict.quizTitle} (1/${started.total})\n\n❓ ${q.questionUz}`
    );
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildQuizQuestionKeyboard(user.language, q.optionsUz, ctx.emojiRegistry),
    });
    return { handled: true, action: 'quiz:start' };
  }

  if (data.startsWith('quiz:ans:')) {
    const optIdx = Number(data.slice('quiz:ans:'.length)) || 0;
    const fullName = [user.firstName, user.lastName].filter(Boolean).join(' ');
    const ans = await ctx.academyQuizService.submitQuizAnswer(
      user.telegramId,
      fullName,
      optIdx,
      user.language
    );
    await ctx.apiClient.answerCallbackQuery({
      callback_query_id: callback.id,
      text: ans.isCorrect ? '✅ Toʻgʻri javob!' : '❌ Notoʻgʻri javob',
    });

    if (ans.finished) {
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.quizFinishedTitle}\n\n` +
          `• Natija: ${ans.score} / ${ans.total}\n` +
          `• Toʻplangan ball: +${ans.pointsEarned}\n\n` +
          (ans.explanation ? `💡 ${ans.explanation}` : '')
      );
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildQuizResultKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: data };
    }

    const nextQ = ctx.academyQuizService.getCurrentQuizQuestion(user.telegramId);
    if (!nextQ) {
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: dict.quizEmpty,
        reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: data };
    }

    const feedback = `${ans.isCorrect ? '✅ Toʻgʻri!' : '❌ Xato.'} ${ans.explanation ? `\n💡 ${ans.explanation}\n\n` : '\n\n'}`;
    const formatted = ctx.emojiRegistry.formatMessage(
      `${feedback}${dict.quizTitle} (${nextQ.index + 1}/${nextQ.total})\n\n❓ ${nextQ.question.questionUz}`
    );
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildQuizQuestionKeyboard(
        user.language,
        nextQ.question.optionsUz,
        ctx.emojiRegistry
      ),
    });
    return { handled: true, action: data };
  }

  if (data === 'quiz:leaderboard') {
    const formatted = ctx.academyQuizService.formatLeaderboardMessage(
      user.language,
      ctx.emojiRegistry
    );
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildQuizResultKeyboard(user.language, ctx.emojiRegistry),
    });
    return { handled: true, action: 'quiz:leaderboard' };
  }

  // 8. Media Library: library:view:<kind>:<idx> & bookmark:media:<kind>:<idx>
  if (data.startsWith('library:view:')) {
    const parts = data.split(':');
    const rawKind = parts[2];
    const kind: 'articles' | 'news' | 'announcements' | 'adhan' | 'audio' | 'video' =
      rawKind === 'news' ||
      rawKind === 'announcements' ||
      rawKind === 'adhan' ||
      rawKind === 'audio' ||
      rawKind === 'video'
        ? rawKind
        : 'articles';
    const idx = Number(parts[3]) || 0;
    const res = ctx.contentAdapter.formatMediaLibraryItem(
      kind,
      idx,
      user.language,
      ctx.emojiRegistry
    );
    if (res.itemId) {
      if (kind === 'articles') {
        await ctx.contentAdapter.recordArticleRead(ctx.repository, user.telegramId, res.itemId);
      } else if (kind === 'video') {
        await ctx.contentAdapter.recordVideoWatched(ctx.repository, user.telegramId, res.itemId);
      } else if (kind === 'audio' || kind === 'adhan') {
        await ctx.contentAdapter.recordAudioResume(
          ctx.repository,
          user.telegramId,
          res.itemId,
          res.itemTitle || kind
        );
      }
    }
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: res.formatted.text,
      entities: res.formatted.entities,
      reply_markup: buildMediaLibraryKeyboard(
        user.language,
        kind,
        res.index,
        res.total,
        ctx.emojiRegistry,
        res.itemId
      ),
    });
    return { handled: true, action: data };
  }

  if (data.startsWith('bookmark:media:')) {
    const parts = data.split(':');
    const rawKind = parts[2];
    const kind: 'articles' | 'news' | 'announcements' | 'adhan' | 'audio' | 'video' =
      rawKind === 'news' ||
      rawKind === 'announcements' ||
      rawKind === 'adhan' ||
      rawKind === 'audio' ||
      rawKind === 'video'
        ? rawKind
        : 'articles';
    const idx = Number(parts[3]) || 0;
    const item = ctx.contentAdapter.formatMediaLibraryItem(
      kind,
      idx,
      user.language,
      ctx.emojiRegistry
    );
    const bookmarkKind =
      kind === 'articles'
        ? 'article'
        : kind === 'news'
          ? 'news'
          : kind === 'announcements'
            ? 'announcement'
            : kind === 'video'
              ? 'video'
              : 'audio';
    const refId = item.itemId || `${kind}_${idx}`;
    const toggled = await ctx.contentAdapter.toggleBookmark(ctx.repository, user.telegramId, {
      id: `${bookmarkKind}_${refId}`,
      kind: bookmarkKind,
      refId,
      title: item.itemTitle || `${kind} #${idx + 1}`,
    });
    await ctx.apiClient.answerCallbackQuery({
      callback_query_id: callback.id,
      text: toggled.saved ? dict.bookmarkSavedToast : dict.bookmarkRemovedToast,
    });
    return { handled: true, action: data };
  }

  // 8B. Official Android App Section: nav:android_app | android:check | android:guide | android:history
  if (data === 'nav:android_app' || data === 'android:check') {
    const isRefresh = data === 'android:check';
    const info = await ctx.appReleaseService.getResolvedReleaseInfo({
      checkGitHub: isRefresh,
      forceRefresh: isRefresh,
    });
    const card = ctx.appReleaseService.formatTelegramAndroidAppCard(
      info,
      user.language,
      ctx.emojiRegistry
    );
    await ctx.apiClient.answerCallbackQuery({
      callback_query_id: callback.id,
      ...(isRefresh
        ? { text: `v${info.version} — ${info.apkAvailable ? 'APK tayyor' : 'Tekshirildi'}` }
        : {}),
    });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: card.text,
      entities: card.entities,
      reply_markup: buildAndroidAppKeyboard(
        user.language,
        info,
        ctx.emojiRegistry,
        ctx.config,
        menuOpts.miniAppEnabled
      ),
    });
    return { handled: true, action: data };
  }

  if (data === 'android:guide') {
    const info = await ctx.appReleaseService.getResolvedReleaseInfo({ checkGitHub: false });
    const formatted = ctx.appReleaseService.formatTelegramAndroidAppCard(
      info,
      user.language,
      ctx.emojiRegistry,
      'install_guide'
    );
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildAndroidAppKeyboard(
        user.language,
        info,
        ctx.emojiRegistry,
        ctx.config,
        menuOpts.miniAppEnabled
      ),
    });
    return { handled: true, action: 'android:guide' };
  }

  if (data === 'android:history') {
    const info = await ctx.appReleaseService.getResolvedReleaseInfo({ checkGitHub: false });
    const formatted = ctx.appReleaseService.formatTelegramAndroidAppCard(
      info,
      user.language,
      ctx.emojiRegistry,
      'history'
    );
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildAndroidAppKeyboard(
        user.language,
        info,
        ctx.emojiRegistry,
        ctx.config,
        menuOpts.miniAppEnabled
      ),
    });
    return { handled: true, action: 'android:history' };
  }

  // 9. Support Center: support:cat:<category> | support:my_tickets
  if (data.startsWith('support:cat:')) {
    const cat = data.slice('support:cat:'.length) as TelegramSupportTicketCategory;
    await ctx.userService.setActiveFlow(user.telegramId, {
      type: 'support_new',
      category: cat,
    });
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    const formatted = ctx.emojiRegistry.formatMessage(
      `${dict.supportTitle}\n\n${dict.supportWritePrompt}`
    );
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
    });
    return { handled: true, action: data };
  }

  if (data === 'support:my_tickets') {
    const tickets = ctx.supportService.listUserTickets(user.telegramId);
    const body =
      tickets.length === 0
        ? dict.supportEmptyTickets
        : tickets
            .slice(0, 8)
            .map(
              (t) =>
                `• [${t.id}] (${t.status}) — ${t.subject}\n  Oxirgi xabar: ${t.messages.at(-1)?.text.slice(0, 90) || ''}`
            )
            .join('\n\n');
    const formatted = ctx.emojiRegistry.formatMessage(`${dict.supportTitle}\n\n${body}`);
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildSupportHomeKeyboard(user.language, ctx.emojiRegistry),
    });
    return { handled: true, action: 'support:my_tickets' };
  }

  // 10. AI Memory Clear
  if (data === 'ai:clear') {
    await ctx.aiBridge.clearConversationHistory(user.telegramId);
    await ctx.apiClient.answerCallbackQuery({
      callback_query_id: callback.id,
      text: dict.aiClearHistoryToast,
    });
    return { handled: true, action: 'ai:clear' };
  }

  // 11. RBAC-Protected Super Admin Callbacks: admin:*
  if (data.startsWith('admin:')) {
    if (!role) {
      await ctx.repository.appendAuditLog({
        actorTelegramId: user.telegramId,
        actorRole: 'user',
        action: 'admin_callback_denied',
        targetType: 'admin',
        targetId: data,
      });
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: dict.adminAccessDenied,
        show_alert: true,
      });
      return { handled: true, action: 'admin:denied' };
    }

    if (data === 'admin:home') {
      const formatted = formatAdminOverviewText(
        user.language,
        ctx.repository,
        ctx.emojiRegistry,
        ctx.aiBridge
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminHomeKeyboard(user.language, settings, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:home' };
    }

    if (data === 'admin:analytics') {
      const a = ctx.adminService.getDashboardAnalytics();
      const langSummary = Object.entries(a.users.byLanguage)
        .map(([k, v]) => `${k}: ${v}`)
        .join(' | ');
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminTitle} — Analitika\n\n` +
          `• Foydalanuvchilar: ${a.users.total} (24s: ${a.users.activeToday}, 7k: ${a.users.activeWeek}, Blok: ${a.users.blockedCount})\n` +
          `• Tillar: ${langSummary}\n` +
          `• AI: ${a.ai.totalCalls} soʻrov (${a.ai.succeeded} OK / ${a.ai.errors} xato, ~${a.ai.avgLatencyMs}ms)\n` +
          `• Murojaatlar: ${a.support.open} ochiq / ${a.support.answered} javob / ${a.support.closed} yopiq\n` +
          `• Broadcast: ${a.broadcasts.total} ta (${a.broadcasts.completed} yakunlangan)\n` +
          `• Firestore Sync: ${a.firestoreSync.totalWritesSucceeded}/${a.firestoreSync.totalWritesAttempted} OK (xatolar: ${a.firestoreSync.totalWritesFailed})`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminHomeKeyboard(user.language, settings, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:analytics' };
    }

    if (data === 'admin:ai') {
      const st = ctx.aiBridge.getStatus();
      const probeLine = st.lastProbe
        ? `${st.lastProbe.model}: ${st.lastProbe.available ? 'AVAILABLE' : 'UNAVAILABLE'} (${st.lastProbe.latencyMs}ms) — ${st.lastProbe.reason.slice(0, 140)}`
        : 'Hali jonli probe oʻtkazilmagan';
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminTitle} — AI Nazorati\n\n` +
          `• Primary Model: ${st.primaryModel}\n` +
          `• Fallback Model: ${st.fallbackModel || 'Belgilanmagan'} (Auto: ${st.autoFallbackEnabled ? 'ON' : 'OFF'})\n` +
          `• Voice TTS Reply: ${st.voiceReplyEnabled ? 'ON' : 'OFF'}\n` +
          `• Kunlik tokenlar: ${st.dailyTokensUsed} / ${st.dailyBudgetTokens}\n` +
          `• Soʻnggi jonli tekshiruv: ${probeLine}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminAiControlKeyboard(user.language, settings, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:ai' };
    }

    if (data === 'admin:ai:probe') {
      const probe = await ctx.aiBridge.probeModelAvailability();
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: `${probe.model}: ${probe.available ? 'OK' : 'UNAVAILABLE'} (${probe.latencyMs}ms)`,
        show_alert: true,
      });
      return { handled: true, action: 'admin:ai:probe' };
    }

    if (data === 'admin:ai:set_primary') {
      await ctx.userService.setActiveFlow(user.telegramId, {
        type: 'admin_ai_set_model',
        which: 'primary',
      });
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: 'Yangi Primary Gemini model nomini yuboring (masalan: gemini-3.5-flash-lite yoki gemini-2.5-flash):',
        reply_markup: buildAdminAiControlKeyboard(user.language, settings, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:ai:set_primary' };
    }

    if (data === 'admin:ai:toggle_fallback') {
      const updated = await ctx.repository.saveSettings(
        { aiAutoFallbackEnabled: !settings.aiAutoFallbackEnabled },
        user.telegramId
      );
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: dict.settingUpdatedToast,
      });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: `Auto-Fallback: ${updated.aiAutoFallbackEnabled ? 'ON' : 'OFF'}`,
        reply_markup: buildAdminAiControlKeyboard(user.language, updated, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:ai:toggle_fallback' };
    }

    if (data === 'admin:ai:toggle_voice') {
      const updated = await ctx.repository.saveSettings(
        { aiVoiceReplyEnabled: !(settings.aiVoiceReplyEnabled ?? true) },
        user.telegramId
      );
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: dict.settingUpdatedToast,
      });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: `Voice TTS Reply: ${updated.aiVoiceReplyEnabled ? 'ON' : 'OFF'}`,
        reply_markup: buildAdminAiControlKeyboard(user.language, updated, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:ai:toggle_voice' };
    }

    if (data === 'admin:ai:toggle') {
      const updated = await ctx.repository.saveSettings(
        { aiAssistantEnabled: !settings.aiAssistantEnabled },
        user.telegramId
      );
      const formatted = formatAdminOverviewText(
        user.language,
        ctx.repository,
        ctx.emojiRegistry,
        ctx.aiBridge
      );
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: dict.settingUpdatedToast,
      });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminHomeKeyboard(user.language, updated, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:ai:toggle' };
    }

    if (data === 'admin:maintenance:toggle') {
      const updated = await ctx.repository.saveSettings(
        { maintenanceMode: !settings.maintenanceMode },
        user.telegramId
      );
      const formatted = formatAdminOverviewText(
        user.language,
        ctx.repository,
        ctx.emojiRegistry,
        ctx.aiBridge
      );
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: dict.settingUpdatedToast,
      });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminHomeKeyboard(user.language, updated, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:maintenance:toggle' };
    }

    if (data === 'admin:support') {
      const tickets = ctx.supportService.listAllTickets();
      const summary =
        tickets.length === 0
          ? 'Hozircha murojaatlar yoʻq.'
          : tickets
              .slice(0, 6)
              .map((t) => `• [${t.id}] (${t.status}) ${t.userName}: ${t.subject}`)
              .join('\n');
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminTitle} — Murojaatlar (${tickets.length})\n\n${summary}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminSupportKeyboard(user.language, tickets, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:support' };
    }

    if (data.startsWith('admin:support:reply:')) {
      const ticketId = data.slice('admin:support:reply:'.length);
      await ctx.userService.setActiveFlow(user.telegramId, {
        type: 'admin_ticket_reply',
        ticketId,
      });
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: `[${ticketId}] uchun javob matnini yuboring. Javob toʻgʻridan-toʻgʻri foydalanuvchiga yetkaziladi:`,
        reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: data };
    }

    if (data.startsWith('admin:support:close:')) {
      const ticketId = data.slice('admin:support:close:'.length);
      await ctx.supportService.updateTicketStatus(ticketId, user.telegramId, 'closed');
      const tickets = ctx.supportService.listAllTickets();
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: `${ticketId} yopildi.`,
      });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: `Murojaatlar (${tickets.length})`,
        reply_markup: buildAdminSupportKeyboard(user.language, tickets, ctx.emojiRegistry),
      });
      return { handled: true, action: data };
    }

    if (data === 'admin:broadcasts') {
      const campaigns = ctx.repository.listBroadcasts();
      const lines =
        campaigns.length === 0
          ? 'Hozircha broadcast kampaniyalar yoʻq.'
          : campaigns
              .slice(0, 6)
              .map(
                (c) =>
                  `• ${c.title} [${c.status}] — ${c.sentCount}/${c.totalTargets} (Blok: ${c.blockedCount})`
              )
              .join('\n');
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminTitle} — Broadcast Markazi\n\n${lines}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminBroadcastsKeyboard(user.language, campaigns, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:broadcasts' };
    }

    if (data === 'admin:broadcast:new') {
      await ctx.userService.setActiveFlow(user.telegramId, { type: 'admin_broadcast_title' });
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: 'Yangi broadcast kampaniyasi sarlavhasini yozib yuboring:',
        reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:broadcast:new' };
    }

    if (data.startsWith('admin:broadcast:test:')) {
      const bcId = data.slice('admin:broadcast:test:'.length);
      const preview = await ctx.broadcastManager.sendTestPreview(bcId, chatId);
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: preview.ok ? 'Test preview yuborildi!' : (preview.error || 'Xatolik').slice(0, 180),
        show_alert: true,
      });
      return { handled: true, action: data };
    }

    if (data.startsWith('admin:broadcast:start:')) {
      const bcId = data.slice('admin:broadcast:start:'.length);
      const res = await ctx.broadcastManager.runCampaign(bcId, user.telegramId, {
        delayBetweenMessagesMs: 25,
      });
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: res ? `Yakunlandi: ${res.sentCount} sent, ${res.blockedCount} blocked` : 'Topilmadi',
        show_alert: true,
      });
      return { handled: true, action: data };
    }

    if (data.startsWith('admin:broadcast:pause:')) {
      const bcId = data.slice('admin:broadcast:pause:'.length);
      await ctx.broadcastManager.pauseCampaign(bcId, user.telegramId);
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: 'Kampaniya toʻxtatildi (paused).',
      });
      return { handled: true, action: data };
    }

    if (data.startsWith('admin:broadcast:cancel:')) {
      const bcId = data.slice('admin:broadcast:cancel:'.length);
      await ctx.broadcastManager.cancelCampaign(bcId, user.telegramId);
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: 'Kampaniya bekor qilindi.',
      });
      return { handled: true, action: data };
    }

    if (data === 'admin:content') {
      const drafts = ctx.repository.listContentDrafts();
      const body =
        drafts.length === 0
          ? 'Content Studio qoralamalari mavjud emas.'
          : drafts
              .slice(0, 6)
              .map((d) => `• [${d.status}] (${d.type}) ${d.title}`)
              .join('\n');
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminTitle} — Content Studio\n\n${body}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminContentKeyboard(user.language, drafts, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:content' };
    }

    if (data.startsWith('admin:content:publish:')) {
      const draftId = data.slice('admin:content:publish:'.length);
      const res = await ctx.contentStudio.publishDraftToChannels(draftId, user.telegramId);
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: res.ok ? 'Kanalga nashr qilindi!' : (res.error || 'Nashr qilinmadi').slice(0, 180),
        show_alert: true,
      });
      return { handled: true, action: data };
    }

    if (data === 'admin:users') {
      const users = ctx.repository.listUsers();
      const recent = users
        .slice(0, 8)
        .map(
          (u) =>
            `• ${u.telegramId} | ${u.firstName}${u.username ? ` (@${u.username})` : ''} [${u.language}]${u.isBlocked ? ' 🚫' : ''}`
        )
        .join('\n');
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminTitle} — Foydalanuvchilar (${users.length})\n\n${recent || 'Foydalanuvchilar yoʻq.'}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminUsersKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:users' };
    }

    if (data === 'admin:users:search') {
      await ctx.userService.setActiveFlow(user.telegramId, { type: 'admin_user_search' });
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: 'Qidirilayotgan foydalanuvchining Telegram ID, ism yoki @username ini yuboring:',
        reply_markup: buildAdminUsersKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:users:search' };
    }

    if (data === 'admin:channels') {
      const channels = ctx.channelService.listChannels();
      const chLines = channels.map(
        (c) =>
          `• ${c.username} (${c.title}) — ${c.autoPublishPrayerTimes ? 'Auto-Namoz ON' : 'Auto-Namoz OFF'}`
      );
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminChannelsTitle}\n\n${chLines.join('\n')}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminChannelsKeyboard(user.language, channels, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:channels' };
    }

    if (data.startsWith('admin:channel:check:')) {
      const chId = data.slice('admin:channel:check:'.length);
      const perm = await ctx.publishingService.verifyChannelPermissions(chId);
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: perm.reason.slice(0, 190),
        show_alert: true,
      });
      return { handled: true, action: `admin:channel:check:${chId}` };
    }

    if (data.startsWith('admin:channel:publish_prayer:')) {
      const chId = data.slice('admin:channel:publish_prayer:'.length);
      const pub = await ctx.publishingService.publishPrayerScheduleToChannel({
        channelId: chId,
        prayerAdapter: ctx.prayerAdapter,
        createdBy: user.telegramId,
      });
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: pub.success ? 'Namoz jadvali kanalga yuborildi!' : (pub.error || 'Xatolik').slice(0, 190),
        show_alert: true,
      });
      return { handled: true, action: `admin:channel:publish_prayer:${chId}` };
    }

    if (data.startsWith('admin:channel:toggle_auto:')) {
      const chId = data.slice('admin:channel:toggle_auto:'.length);
      const existing = ctx.repository.getChannel(chId);
      if (existing) {
        await ctx.channelService.upsertChannel(user.telegramId, {
          ...existing,
          autoPublishPrayerTimes: !existing.autoPublishPrayerTimes,
        });
      }
      const channels = ctx.channelService.listChannels();
      const chLines = channels.map(
        (c) =>
          `• ${c.username} (${c.title}) — ${c.autoPublishPrayerTimes ? 'Auto-Namoz ON' : 'Auto-Namoz OFF'}`
      );
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminChannelsTitle}\n\n${chLines.join('\n')}`
      );
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: dict.settingUpdatedToast,
      });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminChannelsKeyboard(user.language, channels, ctx.emojiRegistry),
      });
      return { handled: true, action: `admin:channel:toggle_auto:${chId}` };
    }

    if (data === 'admin:prayer') {
      const sched = ctx.prayerAdapter.getCurrentSchedule();
      const lines = sched.times.map((t) => `• ${t.nameUz}: ${t.time}`).join('\n');
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminTitle} — Asaka Namoz Jadvali (Qoʻlda boshqaruv)\n\n` +
          `📅 Sana: ${sched.formattedDateUz || sched.date}\n` +
          `🌙 Hijriy: ${sched.hijriDate}\n\n${lines}\n\n` +
          `Oʻzgartirmoqchi boʻlgan namoz vaqtini tanlang (avtomatik hisoblanmaydi, toʻgʻridan-toʻgʻri Firestore ga saqlanadi):`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminPrayerKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:prayer' };
    }

    if (data.startsWith('admin:prayer:edit:')) {
      const prayerKey = data.slice('admin:prayer:edit:'.length);
      await ctx.userService.setActiveFlow(user.telegramId, {
        type: 'admin_prayer_edit',
        prayerKey,
      });
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: `🕌 «${prayerKey.toUpperCase()}» uchun yangi vaqtni HH:MM formatida yuboring (masalan: 05:15):`,
        reply_markup: buildAdminPrayerKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: data };
    }

    if (data === 'admin:cms') {
      const counts = ctx.contentAdapter.centralContent.getSummaryCounts();
      const recentItems: Array<{ type: 'article' | 'news' | 'announcement' | 'hadith'; id: string; title: string }> = [
        ...ctx.contentAdapter.centralContent.getPublishedArticles().slice(0, 2).map((a) => ({
          type: 'article' as const,
          id: a.id,
          title: a.title,
        })),
        ...ctx.contentAdapter.centralContent.getPublishedAnnouncements().slice(0, 1).map((a) => ({
          type: 'announcement' as const,
          id: a.id,
          title: a.title,
        })),
        ...ctx.contentAdapter.centralContent.getPublishedNews().slice(0, 1).map((n) => ({
          type: 'news' as const,
          id: n.id,
          title: n.title,
        })),
      ];
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminTitle} — Markaziy Firestore CMS\n\n` +
          `• Maqolalar: ${counts.articles}\n` +
          `• Yangiliklar: ${counts.news}\n` +
          `• Eʼlonlar: ${counts.announcements}\n` +
          `• Hadislar: ${counts.hadiths}\n` +
          `• Zikrlar: ${counts.dhikrs}\n` +
          `• Audio/Video: ${counts.audio}/${counts.video}\n\n` +
          `Bu yerda yaratilgan kontent Web App, Android ilova va Telegram botga bir vaqtda saqlanadi.`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminCmsKeyboard(user.language, recentItems, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:cms' };
    }

    if (data.startsWith('admin:cms:new:')) {
      const entityType = data.slice('admin:cms:new:'.length) as 'article' | 'news' | 'announcement' | 'hadith';
      if (['article', 'news', 'announcement', 'hadith'].includes(entityType)) {
        await ctx.userService.setActiveFlow(user.telegramId, {
          type: 'admin_cms_create_title',
          entityType,
        });
        await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
        await renderScreenUpdate(ctx.apiClient, callback, {
          text: `📝 Yangi [${entityType}] uchun sarlavhani yuboring:`,
          reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
        });
      }
      return { handled: true, action: data };
    }

    if (data.startsWith('admin:cms:del_confirm:')) {
      const rest = data.slice('admin:cms:del_confirm:'.length);
      const sep = rest.indexOf(':');
      const entityType = rest.slice(0, sep);
      const itemId = rest.slice(sep + 1);
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: `⚠️ Tasdiqlang: [${entityType}] (ID: ${itemId}) yozuvini arxivlash/oʻchirishni xohlaysizmi?`,
        reply_markup: {
          inline_keyboard: [
            [
              { text: '✅ Ha, oʻchirish', callback_data: `admin:cms:del:${entityType}:${itemId}` },
              { text: '❌ Bekor qilish', callback_data: 'admin:cms' },
            ],
          ],
        },
      });
      return { handled: true, action: data };
    }

    if (data.startsWith('admin:cms:del:')) {
      const rest = data.slice('admin:cms:del:'.length);
      const sep = rest.indexOf(':');
      const entityType = rest.slice(0, sep) as 'article' | 'news' | 'announcement' | 'hadith';
      const itemId = rest.slice(sep + 1);
      if (!ctx.centralAdminWriter) {
        await ctx.apiClient.answerCallbackQuery({
          callback_query_id: callback.id,
          text: 'Markaziy CMS yozish ulanmagan.',
          show_alert: true,
        });
        return { handled: true, action: data };
      }
      const res = await ctx.centralAdminWriter.deleteContentItem({
        entityType,
        id: itemId,
        actorTelegramId: user.telegramId,
      });
      await ctx.repository.appendAuditLog({
        actorTelegramId: user.telegramId,
        actorRole: role,
        action: `cms_delete_${entityType}`,
        targetType: 'content',
        targetId: itemId,
        metadata: { entityType, ok: res.ok, error: res.error || '' },
      });
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: res.ok ? '✅ Yozuv Firestore dan oʻchirildi/arxivlandi.' : (res.error || 'Xatolik').slice(0, 180),
        show_alert: true,
      });
      return { handled: true, action: data };
    }

    if (data === 'admin:channel:connect') {
      await ctx.userService.setActiveFlow(user.telegramId, { type: 'admin_channel_connect' });
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: '📡 Ulash uchun kanal yoki guruh @username (masalan: @Asaka_Ziyo) yoki Chat ID (-100...) ni yuboring. Bot haqiqiy admin huquqlarini Telegram API orqali tekshiradi:',
        reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:channel:connect' };
    }

    if (data.startsWith('admin:channel:remove_confirm:')) {
      const chId = data.slice('admin:channel:remove_confirm:'.length);
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: `⚠️ Kanal/guruh integratsiyasini (${chId}) uzishni tasdiqlaysizmi?`,
        reply_markup: {
          inline_keyboard: [
            [
              { text: '✅ Ha, uzish', callback_data: `admin:channel:remove:${chId}` },
              { text: '❌ Bekor qilish', callback_data: 'admin:channels' },
            ],
          ],
        },
      });
      return { handled: true, action: data };
    }

    if (data.startsWith('admin:channel:remove:')) {
      const chId = data.slice('admin:channel:remove:'.length);
      await ctx.channelService.removeChannel(user.telegramId, chId);
      const channels = ctx.channelService.listChannels();
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: 'Kanal/guruh uzildi.',
      });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: `${dict.adminChannelsTitle}\n\nUlangan kanallar: ${channels.length}`,
        reply_markup: buildAdminChannelsKeyboard(user.language, channels, ctx.emojiRegistry),
      });
      return { handled: true, action: data };
    }

    if (data === 'admin:emojis') {
      const rep = ctx.emojiRegistry.validateCompatibility();
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminEmojisTitle}\n\n` +
          `• Jami semantik slotlar: ${rep.totalRegisteredKeys}\n` +
          `• Tasdiqlangan Custom ID: ${rep.verifiedCustomCount}\n` +
          `• Unicode Fallback: ${rep.fallbackOnlyCount}\n` +
          `• Premium Rendering: ${rep.premiumRenderingActive ? 'ON' : 'OFF (Unicode fallback)'}\n` +
          `• Keyboard Custom Icon: ${rep.keyboardCustomIconsActive ? 'ON' : 'OFF (Unicode fallback)'}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminEmojisKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:emojis' };
    }

    if (data === 'admin:emojis:verify') {
      const ver = await ctx.emojiRegistry.verifyAllWithTelegramApi(ctx.apiClient);
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: `API: ${ver.apiAvailable ? 'OK' : 'OFF'} | Verified: ${ver.verifiedKeys.length} | Rejected: ${ver.rejectedKeys.length}`,
        show_alert: true,
      });
      return { handled: true, action: 'admin:emojis:verify' };
    }

    if (data === 'admin:emojis:test') {
      const testRes = await ctx.emojiRegistry.sendLiveEmojiTestMessage(ctx.apiClient, chatId);
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: testRes.ok
          ? `Test yuborildi (Custom: ${testRes.usedCustomEmojiCount}, Fallback: ${testRes.usedFallbackCount})`
          : (testRes.error || 'Yuborilmadi').slice(0, 180),
        show_alert: true,
      });
      return { handled: true, action: 'admin:emojis:test' };
    }

    if (data === 'admin:diagnostics') {
      const diag = await ctx.runDiagnostics();
      const issueText =
        diag.issues.length > 0 ? diag.issues.join('\n• ') : 'Hech qanday muammo topilmadi.';
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminTitle}\n\n` +
          `• Mode: ${diag.mode} (${diag.startupState})\n` +
          `• Telegram API: ${diag.telegramApi.connected ? `@${diag.telegramApi.botUsername}` : diag.telegramApi.error}\n` +
          `• /start tayyorligi: ${diag.readyToAnswerStart ? 'TAYYOR' : 'TEKSHIRISH KERAK'}\n\n` +
          `• Holat: ${issueText}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminHomeKeyboard(user.language, settings, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:diagnostics' };
    }
  }

  // 12. Standard Navigation & Content Views
  switch (data) {
    case 'nav:home':
    case 'ai:exit': {
      await ctx.userService.setActiveFlow(user.telegramId, { type: 'idle' });
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.mainMenuTitle}\n\n${dict.mainMenuPrompt}`
      );
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        ...(data === 'ai:exit' ? { text: dict.aiExitedToast } : {}),
      });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildMainMenuKeyboard(user.language, ctx.emojiRegistry, ctx.config, menuOpts),
      });
      return { handled: true, action: data };
    }

    case 'nav:prayer':
    case 'prayer:refresh': {
      const formatted = ctx.prayerAdapter.formatPrayerScheduleMessage(
        user.language,
        ctx.emojiRegistry
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildPrayerKeyboard(
          user.language,
          ctx.emojiRegistry,
          ctx.config,
          menuOpts.miniAppEnabled
        ),
      });
      return { handled: true, action: data };
    }

    case 'nav:quran': {
      const res = ctx.contentAdapter.formatQuranDailyAyah(0, user.language, ctx.emojiRegistry);
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: res.formatted.text,
        entities: res.formatted.entities,
        reply_markup: buildQuranKeyboard(
          user.language,
          res.index,
          res.total,
          ctx.emojiRegistry,
          ctx.config,
          menuOpts.miniAppEnabled
        ),
      });
      return { handled: true, action: 'nav:quran' };
    }

    case 'nav:hadith': {
      const res = ctx.contentAdapter.formatHadithCard(0, user.language, ctx.emojiRegistry);
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: res.formatted.text,
        entities: res.formatted.entities,
        reply_markup: buildHadithKeyboard(user.language, res.index, res.total, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:hadith' };
    }

    case 'nav:dhikr': {
      const eng = ctx.repository.getUserEngagement(user.telegramId);
      const probe = ctx.contentAdapter.formatDhikrCard(0, 0, user.language, ctx.emojiRegistry);
      const savedCount = eng.dhikr.countsByDhikrId[probe.dhikrId] || 0;
      const savedGoal = eng.dhikr.dailyGoals[probe.dhikrId];
      const res = ctx.contentAdapter.formatDhikrCard(
        0,
        savedCount,
        user.language,
        ctx.emojiRegistry,
        savedGoal,
        eng.dhikr.todayCount
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: res.formatted.text,
        entities: res.formatted.entities,
        reply_markup: buildDhikrKeyboard(
          user.language,
          res.index,
          res.total,
          savedCount,
          ctx.emojiRegistry
        ),
      });
      return { handled: true, action: 'nav:dhikr' };
    }

    case 'nav:academy': {
      const res = ctx.academyQuizService.formatLessonCard(
        0,
        user.telegramId,
        user.language,
        ctx.emojiRegistry
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: res.formatted.text,
        entities: res.formatted.entities,
        reply_markup: buildAcademyKeyboard(
          user.language,
          res.index,
          res.total,
          res.lessonId,
          ctx.emojiRegistry
        ),
      });
      return { handled: true, action: 'nav:academy' };
    }

    case 'nav:glossary': {
      const formatted = ctx.contentAdapter.formatGlossaryPage(user.language, ctx.emojiRegistry);
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:glossary' };
    }

    case 'nav:mosque': {
      const formatted = ctx.contentAdapter.formatMosqueInfoCard(user.language, ctx.emojiRegistry);
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:mosque' };
    }

    case 'nav:bookmarks': {
      const formatted = formatBookmarksMessageText(user, ctx.repository, ctx.emojiRegistry);
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:bookmarks' };
    }

    case 'nav:search': {
      await ctx.userService.setActiveFlow(user.telegramId, { type: 'global_search' });
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.searchTitle}\n\n${dict.searchPrompt}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:search' };
    }

    case 'nav:support': {
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.supportTitle}\n\n${dict.supportPrompt}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildSupportHomeKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:support' };
    }

    case 'nav:ai': {
      const aiStatus = ctx.aiBridge.getStatus();
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      if (!aiStatus.enabled) {
        const formatted = ctx.emojiRegistry.formatMessage(
          `${dict.aiTitle}\n\n${dict.aiDisabledNotice}`
        );
        await renderScreenUpdate(ctx.apiClient, callback, {
          text: formatted.text,
          entities: formatted.entities,
          reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
        });
        return { handled: true, action: 'nav:ai:disabled' };
      }
      if (!aiStatus.apiKeyConfigured) {
        const formatted = ctx.emojiRegistry.formatMessage(
          `${dict.aiTitle}\n\n${dict.aiMissingKeyNotice}`
        );
        await renderScreenUpdate(ctx.apiClient, callback, {
          text: formatted.text,
          entities: formatted.entities,
          reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
        });
        return { handled: true, action: 'nav:ai:missing_key' };
      }

      ctx.aiBridge.enterAiMode(user.telegramId);
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.aiTitle}\n\n${dict.aiPromptReady}`
      );
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAiModeKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:ai' };
    }

    case 'nav:profile': {
      const formatted = formatProfileMessageText(user, role, ctx.emojiRegistry, ctx.repository);
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildProfileKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:profile' };
    }

    case 'nav:language': {
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.languageTitle}\n\n${dict.languagePrompt}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildLanguageKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:language' };
    }

    case 'nav:settings': {
      const formatted = formatSettingsMessageText(user, ctx.emojiRegistry);
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildSettingsKeyboard(user, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:settings' };
    }

    case 'nav:channels': {
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.channelsTitle}\n\n${dict.channelsBody}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildChannelsKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:channels' };
    }

    case 'nav:help': {
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.helpTitle}\n\n${dict.helpBody}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:help' };
    }

    default: {
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: dict.unknownCommand,
      });
      return { handled: false, action: data || 'unknown' };
    }
  }
}
